import random
import re
from collections import deque

_ALPHABET = "abcdefghijklmnopqrstuvwxyz"
_MAX_N = 200_000
_MAX_ANSWER = 38
_SMALL_CASES = (
    ("a", "a"),
    ("a", "z"),
    ("aa", "ab"),
    ("ab", "ba"),
    ("ab", "bb"),
    ("abac", "abac"),
    ("abac", "abrc"),
    ("abac", "bcba"),
    ("abc", "bca"),
    ("abc", "bcc"),
    ("abc", "baa"),
    ("aaaaaaaa", "zzzzzzzz"),
    ("abcabcab", "zzzzzzzz"),
)


def _parse_input(inp: str) -> tuple[str, str] | None:
    match = re.fullmatch(r"\s*\+?([0-9]+)\s+([a-z]+)\s+([a-z]+)\s*", inp, re.ASCII)
    if match is None:
        return None
    digits, source, target = match.groups()
    digits = digits.lstrip("0")
    if not digits or len(digits) > 6:
        return None
    length = int(digits)
    if length > _MAX_N or len(source) != length or len(target) != length:
        return None
    return source, target


def _format_case(source: str, target: str) -> str:
    return f"{len(source)}\n{source}\n{target}\n"


def validate_input(inp: str) -> bool:
    return _parse_input(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = []
    for index in range(n):
        if index < len(_SMALL_CASES):
            source, target = _SMALL_CASES[index]
        else:
            length = rng.randint(1, 8)
            letters = rng.sample(_ALPHABET, rng.randint(1, 3))
            source = "".join(rng.choices(letters, k=length))
            if index % 2:
                destinations = rng.choices(_ALPHABET, k=len(letters))
                translation = str.maketrans("".join(letters), "".join(destinations))
                target = source.translate(translation)
            else:
                target = "".join(rng.choices(_ALPHABET, k=length))
        cases.append(_format_case(source, target))
    return cases


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    alphabet = "".join(rng.sample(_ALPHABET, len(_ALPHABET)))

    active = alphabet[:25]
    pair_targets = "".join(active[i:i + 2][::-1] for i in range(0, 22, 2))
    cycle_targets = active[23:25] + active[22]
    source = (active * ((_MAX_N + len(active) - 1) // len(active)))[:_MAX_N]
    target = source.translate(str.maketrans(active, pair_targets + cycle_targets))

    full_source = (
        alphabet * ((_MAX_N + len(alphabet) - 1) // len(alphabet))
    )[:_MAX_N]
    full_target = full_source.translate(str.maketrans(alphabet, alphabet[1:] + alphabet[0]))
    return [_format_case(source, target), _format_case(full_source, full_target)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    parsed = _parse_input(inp)
    if parsed is None:
        return [("POST-1", "Input violates the stated constraints.")]
    source, target = parsed

    match = re.fullmatch(r"\s*([+-]?)([0-9]+)\s*", out, re.ASCII)
    if match is None:
        return [("POST-2", "Expected exactly one decimal integer token.")]
    sign, digits = match.groups()
    digits = digits.lstrip("0") or "0"
    if len(digits) > 2:
        return [("POST-6", "Answer is outside the range from -1 to 38.")]
    answer = int(digits)
    if sign == "-":
        answer = -answer
    if not -1 <= answer <= _MAX_ANSWER:
        return [("POST-6", "Answer is outside the range from -1 to 38.")]

    failures = []
    if (answer == 0) != (source == target):
        failures.append(("POST-4", "Answer must be zero exactly when S equals T."))

    if answer >= 0:
        destinations = {}
        changed_letters = set()
        split = False
        for before, after in zip(source, target):
            if destinations.setdefault(before, after) != after:
                split = True
            if before != after:
                changed_letters.add(before)

        if split:
            failures.append(("POST-5", "Equal source positions have different target letters."))
        if source != target and len(set(target)) == len(_ALPHABET):
            failures.append(("POST-5", "A different target using all 26 letters is unreachable."))
        if answer < len(changed_letters):
            failures.append(("POST-6", "Too few operations for the distinct letters that must change."))
    return failures


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index, inp in enumerate(gen_small(seed, n)):
        source, target = inp.split()[1:]
        if index % 3 == 0:
            positions = rng.sample(range(len(source)), len(source))
            source2 = "".join(source[i] for i in positions)
            target2 = "".join(target[i] for i in positions)
        elif index % 3 == 1:
            renamed = "".join(rng.sample(_ALPHABET, len(_ALPHABET)))
            translation = str.maketrans(_ALPHABET, renamed)
            source2, target2 = source.translate(translation), target.translate(translation)
        else:
            factor = rng.randint(2, 4)
            source2, target2 = source * factor, target * factor
        if (source2, target2) == (source, target):
            source2, target2 = source * 2, target * 2
        pairs.append(("POST-7", "equal", inp, _format_case(source2, target2)))
    return pairs


def reference_small(inp: str) -> str | None:
    parsed = _parse_input(inp)
    if parsed is None:
        return None
    source, target = parsed
    if source == target:
        return "0\n"
    if len(source) > 8 or len(set(source)) > 3:
        return None

    pending = deque([(source, 0)])
    visited = {source}
    while pending:
        current, distance = pending.popleft()
        for old in sorted(set(current)):
            for new in _ALPHABET:
                if old == new:
                    continue
                successor = current.replace(old, new)
                if successor == target:
                    return f"{distance + 1}\n"
                if successor not in visited:
                    visited.add(successor)
                    pending.append((successor, distance + 1))
    return "-1\n"
